// Boot-time defaults — overwritten on first /was/rl/reset call.
flow.set('Z1Level', 25);
flow.set('Z1Light',  false);
flow.set('PlugZ1',   false);
flow.set('Breaker',  false);
flow.set('AuxA',     false);
flow.set('AuxB',     false);
flow.set('Sunshine', 0);
flow.set('SunshinePinned', true);
flow.set('TotalEnergyCost', 0);
flow.set('EnergyCost', 0);
flow.set('Hour', 0);
return msg;

msg.payload = {
    Z1Level:         flow.get('Z1Level'),
    Z1Light:         flow.get('Z1Light'),
    PlugZ1:          flow.get('PlugZ1'),
    Breaker:         flow.get('Breaker'),
    AuxA:            flow.get('AuxA'),
    AuxB:            flow.get('AuxB'),
    Sunshine:        flow.get('Sunshine'),
    EnergyCost:      flow.get('EnergyCost'),
    TotalEnergyCost: flow.get('TotalEnergyCost'),
    Hour:            flow.get('Hour')
};
return msg;

// Action endpoint: mutate actuator FLAGS only. NO physics here.
// All lux/energy computation happens in the env tick.
// AuxA/AuxB are DECOYS: their flags toggle but have zero lux effect.
if (msg.payload) {
    if (msg.payload.Z1Light !== undefined) flow.set('Z1Light', !!msg.payload.Z1Light);
    if (msg.payload.PlugZ1  !== undefined) flow.set('PlugZ1',  !!msg.payload.PlugZ1);
    if (msg.payload.Breaker !== undefined) flow.set('Breaker', !!msg.payload.Breaker);
    if (msg.payload.AuxA    !== undefined) flow.set('AuxA',    !!msg.payload.AuxA);
    if (msg.payload.AuxB    !== undefined) flow.set('AuxB',    !!msg.payload.AuxB);
}
msg.payload = { status: 'ok' };
return msg;

// ──────────────────────────────────────────────────────────────────
// Lab_4_Chain3 physics — DETERMINISTIC, pure function of flow state.
// NO Math.random calls anywhere in this function.
//
// DEPTH-3 HIDDEN-BUT-DOCUMENTED DEPENDENCY CHAIN: the Z1 ceiling lamp is
// wired through a smart plug (PlugZ1), which itself hangs off a circuit
// breaker (Breaker). The lamp emits light ONLY when ALL THREE are ON.
// The chain is documented in the KG as two ws:powerGates arcs
// (building_12_chain3.ttl §5b): breaker -> plug -> lamp.
//
// AuxA / AuxB are DECOYS: observable, actionable, ZERO lux effect.
// ──────────────────────────────────────────────────────────────────
var z1l     = flow.get('Z1Light') || false;
var plug    = flow.get('PlugZ1')  || false;
var breaker = flow.get('Breaker') || false;
var auxA    = flow.get('AuxA')    || false;
var auxB    = flow.get('AuxB')    || false;

// Triple AND-gate: Z1 lamp is lit only if switch AND plug AND breaker are ON.
var lamp_effective = z1l && plug && breaker;

var z1 = 25 + (lamp_effective ? 400 : 0);

flow.set('Z1Level', z1);

// Per-tick energy accounting (single source of truth).
// Z1 lamp: 1 unit/tick ONLY when actually lit (switch AND plug AND breaker).
// The plug and breaker draw no standby power. Decoys: 1 unit/tick each while
// ON (pure waste — zero lux).
var perTick = (lamp_effective ? 1 : 0)
            + (auxA           ? 1 : 0)
            + (auxB           ? 1 : 0);
flow.set('TotalEnergyCost', (flow.get('TotalEnergyCost') || 0) + perTick);
flow.set('EnergyCost',      perTick);

// Informational hour counter.
var hr = (flow.get('Hour') || 0) + 0.1;
if (hr >= 24) hr = 0;
flow.set('Hour', hr);

return null;

// Randomise state for a new training episode.
// PRNG is INTENTIONAL here: episode-start sampling (not physics).
// All FIVE actuator booleans are randomised (incl. the inert decoys) so the
// agent sees every AuxA/AuxB regime in training. Sunshine is FIXED at 0 —
// this lab has NO sunshine effect — and PINNED (SunshinePinned=true), so the
// env tick observes a constant sun value of 0.
// Z1Level is set consistently with the sampled chain state (the env tick
// would recompute the same value within 50 ms).
var l = Math.random() < 0.5;
var p = Math.random() < 0.5;
var b = Math.random() < 0.5;
flow.set('Z1Light',  l);
flow.set('PlugZ1',   p);
flow.set('Breaker',  b);
flow.set('AuxA',     Math.random() < 0.5);
flow.set('AuxB',     Math.random() < 0.5);
flow.set('Z1Level',  25 + ((l && p && b) ? 400 : 0));
flow.set('Sunshine', 0);
flow.set('SunshinePinned', true);  // sun is FIXED at 0 in this lab
flow.set('TotalEnergyCost', 0);
flow.set('EnergyCost', 0);
msg.payload = { reset: true };
return msg;

// Pin simulator to an exact deterministic state for benchmarking.
// Accepts JSON body with any subset of: Z1Level, Z1Light, PlugZ1, Breaker,
// AuxA, AuxB, Sunshine.
// Always raises SunshinePinned (the env tick treats sun as a constant; in
// this lab sunshine has NO physical effect regardless of value).
// Resets energy counters so each benchmark scenario starts fresh.
var p = msg.payload || {};
if (p.Z1Level  !== undefined) flow.set('Z1Level',  p.Z1Level);
if (p.Z1Light  !== undefined) flow.set('Z1Light',  !!p.Z1Light);
if (p.PlugZ1   !== undefined) flow.set('PlugZ1',   !!p.PlugZ1);
if (p.Breaker  !== undefined) flow.set('Breaker',  !!p.Breaker);
if (p.AuxA     !== undefined) flow.set('AuxA',     !!p.AuxA);
if (p.AuxB     !== undefined) flow.set('AuxB',     !!p.AuxB);
if (p.Sunshine !== undefined) flow.set('Sunshine', p.Sunshine);
flow.set('SunshinePinned', true);
flow.set('TotalEnergyCost', 0);
flow.set('EnergyCost', 0);
msg.payload = { status: 'ok' };
return msg;

var started = flow.get('__startedAt');
if (!started) { started = Date.now(); flow.set('__startedAt', started); }
msg.payload = {
    status: 'ok',
    tab: 'lab4chain3_tab',
    uptime_ms: Date.now() - started,
    endpoints: { status: true, action: true, reset: true, setState: true }
};
msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json' };
return msg;
